/usr/bin/bash -lc "python - <<'PY'
import glob,json,re,os
names=['Learner Tien','Jakub Mensik','Giovanni Mpetshi Perricard','Denis Shapovalov','Alex Michelsen','Cameron Norrie']
for name in names:
 print('\\n###',name); hits=[]
 for p in glob.glob('articles/2026/06/*/articles.jsonl'):
  for line in open(p):
   try:a=json.loads(line)
   except:continue
   c=a.get('content','')
   if name.lower() in c.lower():
    for m in re.finditer(re.escape(name),c,re.I):
     sn=c[max(0,m.start()-220):m.end()+320].replace('\\n',' ')
     if re.search(r'rank|seed|world No|number',sn,re.I): hits.append((a.get('date_publish',''),a.get('title',''),sn))
 for h in hits[-8:]: print(h[0],'|',h[1],'|',h[2])
PY"

